import Link from "next/link";

export default function HomePage() {
  return (
    <main
      style={{
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        backgroundColor: "#78828bff",
        color: "#333",
        textAlign: "center",
      }}
    >
      <h1 style={{ fontSize: "2.5rem", marginBottom: "1rem" }}>
        🧾 HR Employee Report System
      </h1>
      <p style={{ maxWidth: "600px", marginBottom: "2rem", lineHeight: "1.5" }}>
        Welcome to the HR Employee Reporting Dashboard.  
        View, filter, and analyze employee records including registration details,
        department, designation, and status information — all in one place.
      </p>
      <Link
        href="/reports"
        style={{
          backgroundColor: "#0070f3",
          color: "white",
          padding: "12px 24px",
          borderRadius: "8px",
          textDecoration: "none",
          fontWeight: "bold",
          transition: "0.3s",
        }}
        onMouseOver={(e) => (e.target.style.backgroundColor = "#0059c1")}
        onMouseOut={(e) => (e.target.style.backgroundColor = "#0070f3")}
      >
        View Employee Report
      </Link>
    </main>
  );
}

